ent.amount:'||id||':'||coalesce("amount"::text,'-') x from "CashMovement" union all select 'StockPurchase.totalCost:'||id||':'||coalesce("totalCost"::text,'-') x from "StockPurchase" union all select 'StockPurchaseItem.unitCost:'||id||':'||coalesce("unitCost"::text,'-') x from "StockPurchaseItem" union all select 'StockPurchaseItem.lineTotal:'||id||':'||coalesce("lineTotal"::text,'-') x from "StockPurchaseItem" union all select 'StockMovement.unitCost:'||id||':'||coalesce("unitCost"::text,'-') x from "StockMovement") s
